# Generated by Claudian.
"""Base types for the skills system.

Keeping this intentionally tiny.  A skill is just:

    name + priority + match(text) -> SkillMatch | None
                    + run(text, entities) -> SkillResult

That's it.  No plugin lifecycle, no dependency injection.  Skills are
short-lived callables; state lives in the modules they import (e.g. the
singleton WhatsApp instance in `automation/whatsapp_automation.py`).
"""

from __future__ import annotations

from dataclasses import dataclass, field
from typing import TYPE_CHECKING, Optional

if TYPE_CHECKING:
    from core.confirmation import PendingAction


@dataclass
class SkillMatch:
    """Result of a skill's `.match(text)` call.

    `confidence` is a 0..1 score.  The registry picks the highest-confidence
    match across all skills.  Anything below `HIGH_CONFIDENCE_THRESHOLD`
    (0.85) triggers an LLM tie-breaker via `ai.intent_classifier`.
    """

    confidence: float
    entities: dict = field(default_factory=dict)


@dataclass
class SkillResult:
    """Outcome of a skill's `.run()` call.

    `text` is what Jarvis speaks back to the user.  `should_shutdown` is
    True only for the `shutdown_jarvis` skill — everything else returns False.
    `already_spoken` is True when the skill streamed its reply directly to
    TTS (e.g. ConversationSkill streaming Groq output sentence-by-sentence);
    in that case the assistant must NOT speak `text` again.
    """

    text: str
    should_shutdown: bool = False
    already_spoken: bool = False
    # Set by irreversible skills. `text` becomes the question asked, and the
    # action runs only if the user approves. The skill hands over a callable
    # rather than executing and reporting, so it cannot approve itself.
    # See core/confirmation.py.
    confirm: "Optional[PendingAction]" = None


class Skill:
    """Base class — subclass this in `skills/<name>.py`."""

    # Unique identifier, also used as the intent name for LLM fallback.
    name: str = ""

    # Human-readable description (shown to the LLM when it's asked to classify).
    description: str = ""

    # Lower priority = checked earlier.  Use this to route between overlapping
    # patterns (e.g. "open youtube" should hit open_website before open_app).
    priority: int = 50

    def match(self, text: str) -> Optional[SkillMatch]:
        """Return a SkillMatch if this skill can handle `text`, else None.

        `text` is already lowercased + stripped of surrounding whitespace,
        but still contains the wake word prefix IF the wake-detector couldn't
        strip it (rare — usually stripped before the router sees it).
        """
        raise NotImplementedError

    async def run(self, text: str, entities: dict) -> SkillResult:
        """Execute the skill with the given entities, return what to speak."""
        raise NotImplementedError

    # ── Optional hooks ────────────────────────────────────────────────────────

    def describe_for_llm(self) -> str:
        """One-line description the LLM fallback sees when asked to classify."""
        return f"{self.name}: {self.description}"


# Threshold used by the registry: a match at or above this skips the LLM.
HIGH_CONFIDENCE_THRESHOLD = 0.85
